Cleanup function cancels pending timers on each keystroke → API fires 300ms after typing stops, not on every key.

**Reusable hook** (if wrapping multiple inputs):

```jsx
function useDebouncedValue(value, delay) {
  const [debouncedValue, setDebouncedValue] = useState(value);

  useEffect(() => {
    const timer = setTimeout(() => setDebouncedValue(value), delay);
    return () => clearTimeout(timer);
  }, [value, delay]);

  return debouncedValue;
}

// Usage:
const debouncedQuery = useDebouncedValue(query, 300);
useEffect(() => {
  if (debouncedQuery.trim()) {
    fetch(`/api/search?q=${encodeURIComponent(debouncedQuery)}`)
      .then(r => r.json())
      .then(setResults);
  }
}, [debouncedQuery]);
```

**Vanilla JS** (no React):

```js
function debounce(fn, delay) {
  let timer;
  return function(...args) {
    clearTimeout(timer);
    timer = setTimeout(() => fn(...args), delay);
  };
}

const search = debounce((query) => {
  fetch(`/api/search?q=${encodeURIComponent(query)}`)
    .then(r => r.json())
    .then(results => console.log(results));
}, 300);

document.querySelector('input').addEventListener('input', (e) => {
  search(e.target.value);
});
```

Pick the first (inline) for quick React integration, the hook for multiple uses, vanilla for no framework.
